"""Construye el informe local a partir de resultados, sin recalcular modelos."""
from pathlib import Path
import sys,json,hashlib,html
P=Path(__file__).parent;ROOT=P.parents[1]
sys.path.insert(0,str(ROOT/'.stockquest-local/analitica/python'))
import numpy,pandas,matplotlib,sklearn
env={'python':sys.version,'numpy':numpy.__version__,'pandas':pandas.__version__,'matplotlib':matplotlib.__version__,'scikit-learn':sklearn.__version__,'weka':'3.8.6','java':'21.0.11','jar_sha256':{f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in (ROOT/'.stockquest-local/analitica').glob('*.jar')}}
(P/'entorno.json').write_text(json.dumps(env,indent=2),encoding='utf8')
figures=[
('01_exploracion','Demanda y variación temporal','100.000 registros sintéticos. Media 48,59; desviación 22,77; rango 10–192 unidades. Las fluctuaciones agregadas y promociones desaconsejan borrar valores extremos por rutina.'),
('02_matriz_dispersion','Dispersión y distribución de las clases','Muestra reproducible de 1.800 filas de entrenamiento. Verde: sin presión; naranja: presión. La demanda objetivo solo aparece como exploración. Las medias históricas tienen asociación con demanda futura; la separación no demuestra causalidad.'),
('02b_correlaciones','Matriz de correlación','Pearson sobre entrenamiento. Redundancia entre medias y lags puede volver inestables los coeficientes de una regresión lineal. Los árboles no requieren normalización para comparar umbrales.'),
('08_error_horizonte','Error por horizonte','MAE de prueba: 3,13 / 3,30 / 3,37 / 3,50 unidades. El baseline semanal alcanza 4,41. La degradación con el horizonte expresa mayor incertidumbre. Modelos elegidos por validación, no por prueba.'),
('07_regresion_residuos','Predicciones y residuos','La diagonal es acierto perfecto. El error real−predicción presenta sesgo −0,96: sobreestimación media. La dispersión aumenta con el nivel de demanda. IC95% aproximado del MAE h1: 3,00–3,28; bootstrap de bloques de siete fechas.'),
('03_roc_pr','ROC y Precision–Recall','J48: AUC 0,974; AP 0,922. La referencia PR es la prevalencia 24,33%. Estas curvas corresponden a presión de demanda, definida como demanda de mañana > 1,2 × media semanal conocida hoy; no a agotamiento físico.'),
('04_margen_coste','Margen probabilístico y coste','Margen=(2y−1)(2p−1). Negativo implica error al umbral 0,5. Para operación se eligió 0,09 en validación minimizando (5FN+FP)/N. Esa relación de costes es un supuesto revisable del laboratorio; no se recalibró con prueba.'),
('05_errores_calibracion','Errores y calibración','En 15.000 casos: TN=10.093; FP=1.257; FN=115; TP=3.535. Recall 96,85% y precisión 73,77%. Brier 0,0523. Una curva ROC alta no implica probabilidades perfectamente calibradas.'),
('06_frontera_condicional','Frontera del clasificador WEKA','Sección bidimensional del J48 completo: variar demanda de hoy y media semanal, fijando el resto de atributos. El escalón es consistente con una regla del árbol. No representa todos los contextos y puede incluir combinaciones fuera del soporte de los datos.')]
parts=['<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stock-Quest · CRISP-DM</title><style>body{margin:0;background:#f3f6f9;color:#102a43;font:18px/1.6 system-ui}main{max-width:1100px;margin:auto;padding:45px 28px}h1{font-size:44px;line-height:1.15}h2{margin-top:60px;font-size:29px}img{width:100%;height:auto;background:white}a{color:#006e72}nav{display:flex;gap:20px;flex-wrap:wrap}p{max-width:960px}.metric{font-size:28px;color:#006e72}footer{margin-top:60px;border-top:1px solid #bcccdc} @media print{section{break-inside:avoid}nav{display:none}}</style><main><h1>Stock-Quest<br>Minería de datos para anticipar demanda</h1><p>CRISP-DM · WEKA 3.8.6 · 25 de noviembre de 2026<br>Datos sintéticos; evaluación temporal y prototipo offline.</p><nav><a href="GUIA_CRISP_DM.md">Guía técnica</a><a href="metricas_regresion.csv">Métricas</a><a href="pedidos_propuestos_simulacion.csv">200 recomendaciones</a><a href="verificacion.json">Verificación</a></nav><p class="metric">29,03% menos MAE a un día frente al baseline semanal</p><p>RandomForest ganó en validación para h1–h4. El conjunto de prueba abarca 10/09–23/11/2026. Se conserva separado del ajuste. J48 fue elegido para la clase auxiliar por una diferencia pequeña de AUC en validación, sin prueba de superioridad estadística.</p>']
for name,title,text in figures:
    parts.append(f'<section><h2>{html.escape(title)}</h2><p>{html.escape(text)}</p><a href="graficas/{name}.svg"><img src="graficas/{name}.png" alt="{html.escape(title)}" loading="lazy"></a></section>')
parts.append('<h2>De pronóstico a recomendación</h2><p>Pedido = ceil(max(0, suma de h1–h4 + stock de seguridad − stock final − pedidos pendientes)). La seguridad usa el percentil 95 del máximo error acumulado positivo en 72 orígenes de validación por serie. El archivo contiene 200 decisiones hipotéticas desde el estado baseline del 23/11/2026; no se ejecutaron pedidos ni un replay completo de política.</p><h2>Integración propuesta</h2><p>La capacidad de decisiones de simulación conserva la propiedad del inventario. Application define un puerto de pronóstico; Infrastructure implementa WEKA. El gateway compone HTTP sin acceso SQL. Versionar modelo, esquema, corte de datos y fallback al naive. Antes de automatizar, medir stock medio, demanda perdida, fill rate y servicio por ciclo bajo una política simulada completa.</p><h2>Límites de la evidencia</h2><p>Solo hay ocho agotamientos en el historial. La clase de presión de demanda es un indicador didáctico distinto. El 95% de servicio es un objetivo, no un resultado certificado. No se midieron ahorros monetarios ni generalización a datos reales. No se ejecutó la GUI de WEKA; los modelos se entrenaron con su API Java.</p><footer><p>Fuentes: historial y generador Stock-Quest del 24/11/2026; métricas reproducibles de esta carpeta; <a href="https://www.ibm.com/docs/en/spss-modeler/saas?topic=dm-crisp-help-overview">CRISP-DM IBM</a>; <a href="https://ml.cms.waikato.ac.nz/weka/downloading.html">WEKA oficial</a>; <a href="https://otexts.com/fpp3/tscv.html">validación temporal</a>.</p></footer></main></html>')
(P/'INFORME.html').write_text('\n'.join(parts),encoding='utf8')
print('INFORME.html y entorno.json generados')
